// Action Recommendation Layer — driven by Parse AI Channel Plan's chosen channel sequence
// (AI recommendation, Phase 5, with template-fallback if the AI call fails or returns invalid output).
const cfg = $('Get Config').first().json || {};
let ENV; try { ENV = $env.TRACKING_BASE_URL; } catch (e) { ENV = undefined; }
const baseUrl = (cfg.tracking_base_url && String(cfg.tracking_base_url).trim()) || ENV || 'https://example.com';

const item = $('Mark Brief Approved').first().json;
const account = item.company || 'unknown-account';
const runId   = item.id;
const campaignId = $('Insert Campaign').first().json.id;

let rp = {};
try { rp = typeof item.raw_payload === 'string' ? JSON.parse(item.raw_payload) : (item.raw_payload || {}); } catch (e) { rp = {}; }
const bg = Array.isArray(rp.buying_group) ? rp.buying_group : [];
const emailDraft = (rp.outreach && rp.outreach.action) || (rp.element_4 && rp.element_4.first_step) || '';
const theMove = (rp.element_4 && rp.element_4.the_move) || '';

const confirmed = bg.find(m => ['CONFIRMED','COMPLETE'].includes(String(m.status || '').toUpperCase()));
const primary = confirmed || bg[0] || { name: 'Primary contact (needs enrichment)', focus_area: '' };
const targetName = primary.name || 'Primary contact';

const META = {
  linkedin_connect: { metric:'linkedin_accept', channel:'linkedin', medium:'connect',    web:false },
  linkedin_engage:  { metric:'profile_visit',   channel:'linkedin', medium:'engage',     web:false },
  email:            { metric:'reply_or_meeting',channel:'email',    medium:'outbound',   web:true  },
  invite:           { metric:'registration',    channel:'email',    medium:'event',      web:true  },
  landing_page:     { metric:'page_visits',     channel:'web',      medium:'landing',    web:true  },
  content_download: { metric:'content_download', channel:'web',     medium:'content_dl', web:true  },
  ads:              { metric:'page_visits',     channel:'ads',      medium:'retarget',   web:true  },
  webinar:          { metric:'registration',    channel:'webinar',  medium:'invite',     web:true  },
  phone:            { metric:'call_connected',  channel:'phone',    medium:'call',       web:false },
  partner:          { metric:'partner_response',channel:'partner',  medium:'intro',      web:false }
};

// Plan now comes from Parse AI Channel Plan — either the AI-recommended channel sequence
// (Phase 5: Channel recommendation AI) or, on AI failure/invalid output, the matched
// campaign_templates row's steps unchanged (Select Campaign Template).
const planRow = $('Parse AI Channel Plan').first().json || {};
let steps = Array.isArray(planRow.steps) ? planRow.steps : [];
if (steps.length === 0) {
  // Fallback safety net if no plan came through at all (should not happen).
  steps = [
    { action_type:'linkedin_engage', reason:'Re-engage an already-warm contact', delay_days:0, channel_source:'template' },
    { action_type:'email',           reason: theMove || 'Go direct for a meeting', delay_days:2, channel_source:'template' }
  ];
}

return steps.map((s, i) => {
  const type = s.action_type;
  const m = META[type] || META.email;
  const priority = i + 1;
  const delay_days = typeof s.delay_days === 'number' ? s.delay_days : i * 3;
  const scheduled_for = new Date(Date.now() + delay_days * 86400000).toISOString();
  const rand = Math.random().toString(36).slice(2,5);
  const utm_campaign = 'act-' + runId + '-p' + priority + '-' + rand;
  const sep = baseUrl.includes('?') ? '&' : '?';
  const tracked_url = m.web ? (baseUrl + sep + 'utm_source=' + m.channel + '&utm_medium=' + m.medium + '&utm_campaign=' + utm_campaign) : null;
  const reason = (type === 'email' && theMove) ? theMove : (s.reason || '');
  const hypothesis = '[P' + priority + '] ' + type.replace(/_/g,' ') + ' → ' + targetName + ' for ' + account + ': expect ' + m.metric.replace(/_/g,' ') + ' within 14 days.';
  return { json: {
    campaign_id: campaignId,
    run_id: runId, account, target: targetName,
    action_type: type, priority, reason,
    delay_days, scheduled_for,
    hypothesis, predicted_metric: m.metric, predicted_direction: 'increase',
    threshold: 1, window_days: 14,
    utm_campaign, tracked_url,
    outreach_draft: type === 'email' ? emailDraft : '',
    channel_source: s.channel_source || 'template',
    channel_reco_reason: s.channel_reco_reason || null,
    status: 'recommended'
  }};
});

const row = $json;
let brief = row.raw_payload;
if (typeof brief === 'string') { try { brief = JSON.parse(brief); } catch (e) { brief = null; } }
if (!brief || typeof brief !== 'object') {
  brief = { meta:{ engine:'WHEN Layer Intelligence Engine', document_type:'account brief', schema_version:'1.1', export_date:new Date().toISOString().slice(0,10) }, account:{ name: row.company || 'unknown' }, signals:[], buying_group:[], human_signals:[] };
}
brief.human_signals = Array.isArray(brief.human_signals) ? brief.human_signals : [];
brief.human_signals.push({ type:'human_rejection', gate:'brief', reason:'rejected_by_human', rejected_at:new Date().toISOString(), source:'delivery_layer', run_id: row.id });
return [{ json: { when_engine_url: row.when_engine_url || '', payload: brief } }];

const crypto = require('crypto');
const SECRET = $('Get HMAC Secret').first().json.value;
function sign(id, action) {
  return crypto.createHmac('sha256', SECRET).update(`action:${id}:${action}`).digest('hex').slice(0, 32);
}
const rows = $('Insert Action').all().map(i => i.json);
rows.sort((a,b) => (a.priority||0) - (b.priority||0));
const account = (rows[0] && rows[0].account) || 'account';
const base = 'https://designprodigy.app.n8n.cloud/webhook/action-approval';
const lines = rows.map(r =>
  r.priority + '. [' + r.action_type + '] → ' + (r.target || 'target') + '\n' +
  '   ' + (r.reason || '') + '\n' +
  '   APPROVE: ' + base + '?id=' + r.id + '&action=approve&sig=' + sign(r.id, 'approve') + '\n' +
  '   REJECT:  ' + base + '?id=' + r.id + '&action=reject&sig=' + sign(r.id, 'reject')
);
const message = 'Recommended action plan for ' + account + ' (' + rows.length + ' actions, prioritized):\n\n' + lines.join('\n\n');
return [{ json: { account, count: rows.length, message } }];

const crypto = require('crypto');
const SECRET = $('Get HMAC Secret').first().json.value;
function sign(id, action) {
  return crypto.createHmac('sha256', SECRET).update(`brief:${id}:${action}`).digest('hex').slice(0, 32);
}
const q = ($('Webhook (brief approve/reject)').item.json.query) || {};
const id = q.id;
const action = q.action;
const sig = q.sig || '';
const idOk = typeof id === 'string' && /^[0-9]+$/.test(id);
const actionOk = action === 'approve' || action === 'reject';
let sigOk = false;
if (idOk && actionOk) {
  const expected = sign(id, action);
  const a = Buffer.from(String(sig));
  const b = Buffer.from(expected);
  sigOk = a.length === b.length && crypto.timingSafeEqual(a, b);
}
const valid = idOk && actionOk && sigOk;
return [{ json: { valid, query: { id: idOk ? id : '', action: actionOk ? action : '' } } }];

const approved = $('Mark Brief Approved').first().json;
const ctx = $json;

let rp = {};
try { rp = typeof approved.raw_payload === 'string' ? JSON.parse(approved.raw_payload) : (approved.raw_payload || {}); } catch (e) { rp = {}; }
const industry = (rp.account && rp.account.industry) || '';
const theme = (rp.account && rp.account.theme) || '';
const bg = Array.isArray(rp.buying_group) ? rp.buying_group : [];
const bgSummary = bg.length
  ? bg.map(m => (m.name || 'Unnamed') + ' (' + (m.title || 'no title') + ', ' + (m.focus_area || 'n/a') + ') — ' + (m.status || 'unknown status')).join('; ')
  : 'No buying-group contacts identified yet.';

const tmplRaw = $('Select Campaign Template').first().json || {};
let templateSteps = tmplRaw.steps;
if (typeof templateSteps === 'string') { try { templateSteps = JSON.parse(templateSteps); } catch (e) { templateSteps = []; } }
if (!Array.isArray(templateSteps)) templateSteps = [];

const priorActions = ctx.prior_actions || [];
const priorSummary = priorActions.length
  ? priorActions.map(a => a.action_type + ' (' + a.status + ', ' + a.on_date + ')').join('; ')
  : 'No prior actions recorded for this account yet.';

const perf = ctx.channel_performance || [];
const perfSummary = perf.length
  ? perf.map(p => p.channel + ': ' + p.touches + ' touches, ' + p.conversions + ' conversions (' + (p.conv_rate_pct ?? 0) + '%)').join('; ')
  : 'No engagement/conversion data recorded across the pipeline yet (pre-traffic).';

return [{ json: {
  company: approved.company || 'unknown',
  industry, theme,
  coverage_label: approved.coverage_label || '',
  when_urgency: approved.when_urgency || '',
  when_stage: approved.when_stage || '',
  trigger_type: approved.trigger_type || '',
  buying_group_summary: bgSummary,
  template_key: tmplRaw.key || '',
  template_name: tmplRaw.name || '',
  template_steps_json: JSON.stringify(templateSteps),
  account_score: ctx.account_score ?? 'unknown',
  hard_points: ctx.hard_points ?? 0,
  soft_points: ctx.soft_points ?? 0,
  prior_channels_summary: priorSummary,
  channel_performance_summary: perfSummary
} }];

