parameters.jsCode:
const VOCAB = ['linkedin_connect','linkedin_engage','email','invite','landing_page','content_download','ads','webinar','phone','partner'];

let templateSteps = [];
try {
  const tsJson = $('Build Channel Context').first().json.template_steps_json;
  templateSteps = JSON.parse(tsJson || '[]');
} catch (e) { templateSteps = []; }
if (!Array.isArray(templateSteps) || templateSteps.length === 0) {
  templateSteps = [
    { action_type:'linkedin_engage', reason:'Re-engage an already-warm contact', delay_days:0 },
    { action_type:'email', reason:'Go direct for a meeting', delay_days:2 }
  ];
}

function fallback() {
  return templateSteps.map(s => ({
    action_type: s.action_type,
    delay_days: typeof s.delay_days === 'number' ? s.delay_days : 0,
    reason: s.reason || '',
    channel_source: 'template',
    channel_reco_reason: null
  }));
}

let aiItem = null;
try { aiItem = $('Channel Recommendation AI').first().json; } catch (e) { aiItem = null; }

let plan = null;
try {
  const raw = aiItem && (aiItem.output ?? aiItem.text ?? '');
  if (raw) {
    const cleaned = String(raw).trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/, '')
      .replace(/```\s*$/, '');
    const parsed = JSON.parse(cleaned);
    if (parsed && Array.isArray(parsed.steps)) {
      const summary = parsed.strategy_summary || '';
      const valid = parsed.steps
        .filter(s => s && VOCAB.includes(s.action_type) && Number.isFinite(Number(s.delay_days)) && Number(s.delay_days) >= 0 && Number(s.delay_days) <= 60)
        .slice(0, 8)
        .map(s => ({
          action_type: s.action_type,
          delay_days: Math.round(Number(s.delay_days)),
          reason: String(s.reason || '').slice(0, 300),
          channel_source: 'ai',
          channel_reco_reason: String(s.reason || summary || '').slice(0, 500)
        }));
      if (valid.length > 0) plan = valid;
    }
  }
} catch (e) { plan = null; }

const steps = plan || fallback();
return [{ json: { steps, used_ai: !!plan } }];

const rows = $input.all().map(i => i.json);
if (rows.length === 0) {
  return [{ json: { id: null, key: null, name: null, steps: [], priority: null, template_match_trace: JSON.stringify({ matched_count: 0, winner_key: null, runner_ups: [], reason: 'No campaign_templates row matched this brief on urgency/coverage/stage/keyword filters.' }) } }];
}
const winner = rows[0];
const runnerUps = rows.slice(1).map(r => ({ key: r.key, name: r.name, priority: r.priority }));
const trace = {
  matched_count: rows.length,
  winner_key: winner.key,
  winner_name: winner.name,
  winner_priority: winner.priority,
  runner_ups: runnerUps,
  reason: runnerUps.length
    ? `Matched ${rows.length} templates on urgency/coverage/stage/keyword filters; "${winner.name}" (priority ${winner.priority}) won on lowest priority. Also matched: ${runnerUps.map(r => `${r.name} (priority ${r.priority})`).join(', ')}.`
    : `Only "${winner.name}" matched — no competing templates for this brief.`
};
return [{ json: { ...winner, template_match_trace: JSON.stringify(trace) } }];
